BEGIN;
CREATE TABLE building_catalog (type text PRIMARY KEY, category text NOT NULL, max_level int NOT NULL, unlock_keep_level int NOT NULL, base_cost jsonb NOT NULL, base_build_seconds int NOT NULL, input_rates jsonb NOT NULL DEFAULT '{}', output_rates jsonb NOT NULL DEFAULT '{}', effects jsonb NOT NULL DEFAULT '{}');
CREATE TABLE unit_catalog (type text PRIMARY KEY, category text NOT NULL, attack numeric NOT NULL, defense numeric NOT NULL, training_seconds int NOT NULL, speed numeric NOT NULL, population_cost int NOT NULL, resource_cost jsonb NOT NULL, siege_power numeric NOT NULL DEFAULT 0, rentable boolean NOT NULL DEFAULT false);
COMMIT;
